import sys

def print_digit(x):
    if x == 1:
        print('1')
    else:
        print(f'1')

def main():
    if len(sys.argv) < 2:
        print("Usage: python program.py <number>")
        sys.exit(1)

    num = int(sys.argv[1])
    print_digit(num)

if __name__ == "__main__":
    main()
```

